const fs=require('node:fs'),path=require('node:path');
const base='/var/home/zoltan/.bvm/versions/2.2.94/bit-2.2.94/node_modules/@teambit/';
const {SourceFile}=require(base+'component.sources');
const {parser}=require(base+'semantics.doc-parser');
(async()=>{ const report=[]; for (const [index,source] of JSON.parse(fs.readFileSync('samples.json','utf8')).entries()) {
for(const ext of ['js','cjs']){const name=`sample-${index}.${ext}`, file=path.resolve(name);fs.writeFileSync(file,source);
let writes=[];const result=await parser(SourceFile.load(file,process.cwd(),process.cwd()),{getDocsFromCache:async()=>null,saveDocsInCache:async(key,value)=>writes.push({key,value})});
if(JSON.stringify(result)!=='[]'||writes.length!==1||JSON.stringify(writes[0].value)!=='[]')throw new Error(JSON.stringify({name,result,writes}));
report.push({name,source,result,writes});}}
fs.writeFileSync('results.json',JSON.stringify({node:process.version,bit:'2.2.94',report},null,2)+'\n');console.log(`Verified ${report.length} pinned-parser empty documentation results`);})().catch(error=>{console.error(error);process.exitCode=1;});
